PRAGMA foreign_keys=ON;
BEGIN;
DELETE FROM attack;
COMMIT;
SELECT substr(id,-2), datetime(start_epoch_millis/1000,'unixepoch','+5 hours'), strftime('%w',start_epoch_millis/1000,'unixepoch','+5 hours'), functional_impact, start_zone_id FROM attack ORDER BY start_epoch_millis;
SELECT tag_key, count(*) FROM attack_tag GROUP BY tag_key;
SELECT count(*) FROM intensity_point;
